const generateStyles = (props: ButtonProps): CSSObject => {
  const { currentTheme: theme, variant, styleSlots: styleSlotsProp } = props;
  if (!theme) return {};

  // We are within an Emotion styled component, so we can utilize hooks
  // eslint-disable-next-line react-hooks/rules-of-hooks
  const styleSlots = useMemo(
    () =>
      getStyleSlots<ButtonProps["styleSlots"]>(
        componentName,
        theme,
        variant,
        styleSlotsProp,
        getVariantConfig(theme),
      ),
    [theme, variant, styleSlotsProp],
  );

  return {
    all: "unset",
    boxSizing: "border-box",
    display: "inline-flex",
    alignItems: "center",
    justifyContent: "center",
    textAlign: "center",
    whiteSpace: "nowrap",
    cursor: "pointer",
    width: "fit-content",
    ...theme.typography.label.md,
    height: theme.toRem(32),
    padding: `0 ${theme.toRem(theme.spacing[16])}`,
    borderRadius: theme.button.border.radius,
    border: `${theme.toRem(theme.button.border.width)} solid ${theme.button.primary.color.border.enabled}`,
    backgroundColor: theme.button.primary.color.background.enabled,
    color: theme.button.primary.color.content.enabled,

    "&:hover": {
      backgroundColor: theme.button.primary.color.background.hover,
      color: theme.button.primary.color.content.hover,
      borderColor: theme.button.primary.color.border.hover,
      ...styleSlots?.hover,
    },

    "&:active": {
      backgroundColor: theme.button.primary.color.background.pressed,
      color: theme.button.primary.color.content.pressed,
      borderColor: theme.button.primary.color.border.pressed,
      ...styleSlots?.pressed,
    },

    "&[data-selected]": {
      backgroundColor: theme.button.primary.color.background.selected,
      color: theme.button.primary.color.content.selected,
      borderColor: theme.button.primary.color.border.selected,
      ...styleSlots?.selected,
    },

    "&:disabled, &:disabled:hover": {
      cursor: "not-allowed",
      backgroundColor: theme.button.primary.color.background.disabled,
      borderColor: theme.button.primary.color.border.disabled,
      color: theme.button.primary.color.content.disabled,
      ...styleSlots?.disabled,
    },

    "&:focus-visible": {
      ...theme.focusRing,
      ...styleSlots?.focus,
    },

    [`&.${ButtonClasses.sm}`]: {
      height: theme.toRem(24),
      padding: `0 ${theme.toRem(theme.spacing[8])}`,
      ...theme.typography.label.sm,
      ...styleSlots?.sm,
    },

    [`&.${ButtonClasses.secondary}`]: {
      backgroundColor: theme.button.secondary.color.background.enabled,
      color: theme.button.secondary.color.content.enabled,
      borderColor: theme.button.secondary.color.border.enabled,
      "&:hover": {
        backgroundColor: theme.button.secondary.color.background.hover,
        color: theme.button.secondary.color.content.hover,
        borderColor: theme.button.secondary.color.border.hover,
        ...styleSlots?.secondaryHover,
      },
      "&:active": {
        backgroundColor: theme.button.secondary.color.background.pressed,
        color: theme.button.secondary.color.content.pressed,
        borderColor: theme.button.secondary.color.border.pressed,
        ...styleSlots?.secondaryPressed,
      },
      "&[data-selected]": {
        backgroundColor: theme.button.secondary.color.background.selected,
        color: theme.button.secondary.color.content.selected,
        borderColor: theme.button.secondary.color.border.selected,
        ...styleSlots?.secondarySelected,
      },
      "&:disabled, &:disabled:hover": {
        backgroundColor: theme.button.secondary.color.background.disabled,
        color: theme.button.secondary.color.content.disabled,
        borderColor: theme.button.secondary.color.border.disabled,
        ...styleSlots?.secondaryDisabled,
      },
      ...styleSlots?.secondary,
    },

    [`&.${ButtonClasses.tertiary}`]: {
      backgroundColor: theme.button.tertiary.color.background.enabled,
      color: theme.button.tertiary.color.content.enabled,
      borderColor: theme.button.tertiary.color.border.enabled,
      "&:hover": {
        backgroundColor: theme.button.tertiary.color.background.hover,
        color: theme.button.tertiary.color.content.hover,
        borderColor: theme.button.tertiary.color.border.hover,
        ...styleSlots?.tertiaryHover,
      },
      "&:active": {
        backgroundColor: theme.button.tertiary.color.background.pressed,
        color: theme.button.tertiary.color.content.pressed,
        borderColor: theme.button.tertiary.color.border.pressed,
        ...styleSlots?.tertiaryPressed,
      },
      "&[data-selected]": {
        backgroundColor: theme.button.tertiary.color.background.selected,
        color: theme.button.tertiary.color.content.selected,
        borderColor: theme.button.tertiary.color.border.selected,
        ...styleSlots?.tertiarySelected,
      },
      "&:disabled, &:disabled:hover": {
        backgroundColor: theme.button.tertiary.color.background.disabled,
        color: theme.button.tertiary.color.content.disabled,
        borderColor: theme.button.tertiary.color.border.disabled,
        ...styleSlots?.tertiaryDisabled,
      },
      ...styleSlots?.tertiary,
    },

    [`&.${ButtonClasses.loading}`]: {
      position: "relative",
      pointerEvents: "none", // Prevent interactions while loading

      [`& .${ButtonClasses.content}`]: {
        visibility: "hidden", // Hide content but preserve layout
        opacity: 0,
      },

      ...styleSlots?.loading,
    },

    [`& .${ButtonClasses.loadingWrapper}`]: {
      position: "absolute",
      top: "50%",
      left: "50%",
      transform: "translate(-50%, -50%)",
      display: "flex",
      alignItems: "center",
      justifyContent: "center",
      ...styleSlots?.loadingWrapper,
    },

    [`& .${ButtonClasses.content}`]: {
      display: "flex",
      alignItems: "center",
      justifyContent: "center",
      gap: theme.toRem(theme.spacing[8]),
      ...styleSlots?.content,
    },

    ...styleSlots?.root,
  };
};

// Certain props passed to styled components should not be passed to the DOM element
const excludedDOMProps = getExcludedDOMProps();

// Define the styled component, exclude props from the DOM, generate themed JSS
export const StyledButton = styled("button", {
  shouldForwardProp: (prop) => !excludedDOMProps.includes(prop),
})<ButtonProps>((props) => {
  return generateStyles(props);
});
